<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#E06C75;">  [[DEFAULT]</span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;"> COLLATE</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> 比较规则名称];</span></span>
